ee:variables.ee:set-variable:
%dw 2.0
output application/java
import * from dw::core::Strings
import drop from dw::core::Arrays
fun stripWellKnownAgentCardPath(s0) =
  trim(s0 default "")
    replace /\/\.well-known\/agent-card\.json\/?$/ with ""
    replace /\/\.well-known\/agent\.json\/?$/ with ""

fun ensureHttpScheme(s0) = do {
  var s = trim(s0 default "")
  ---
  if (isEmpty(s)) ""
  else if (startsWith(lower(s), "http://") or startsWith(lower(s), "https://")) s
  else "https://" ++ s
}

/** splitBy "://" avoids substringAfter edge cases; never strip the scheme's // */
fun normalizeBrokerBase(raw0) = do {
  var raw = ensureHttpScheme(stripWellKnownAgentCardPath(raw0 default ""))
  ---
  if (isEmpty(raw)) ""
  else do {
    var parts = raw splitBy "://"
    var schemeKey = lower(parts[0] default "")
    var hostPath = if (sizeOf(parts) < 2) "" else (drop(parts, 1) joinBy "://")
    var hp = trim(hostPath) replace /\/+/ with "/"
    var withScheme = if (isEmpty(hp)) ""
      else if (schemeKey == "https") "https://" ++ hp
      else if (schemeKey == "http") "http://" ++ hp
      else raw
    ---
    if (isEmpty(withScheme)) ""
    else if (!isEmpty(hp) and endsWith(withScheme, "/"))
      trim(withScheme) replace /\/+$/ with ""
    else withScheme
  }
}
---
normalizeBrokerBase(vars.incomingBaseUrl default "")

ee:message.ee:set-payload:
%dw 2.0
output application/json
import * from dw::core::Strings
fun nonEmpty(s) = !isEmpty(trim(s default ""))
var card = payload
var nameOk = nonEmpty(card.name)
var verOk = nonEmpty(card.version)
var hasProto = !isEmpty(card.protocolVersion default "")
var hasCaps = card.capabilities != null and (card.capabilities is Object)
var hasSkills = sizeOf(card.skills default []) > 0
var hasModes = sizeOf(card.defaultInputModes default []) > 0 or sizeOf(card.defaultOutputModes default []) > 0
var a2aOk = hasProto or hasCaps or hasSkills or hasModes
---
if (!nameOk or !verOk)
  { valid: false, error: "Agent card must include non-empty name and version." }
else if (!a2aOk)
  { valid: false, error: "Agent card is not A2A-compatible: need protocolVersion, capabilities, skills, or default input/output modes." }
else
  { valid: true, card: card }

ee:variables.ee:set-variable:
%dw 2.0
output application/java
import * from dw::core::Strings
fun joinBasePath(b, p) = do {
  var base0 = trim(b default "") replace /\/+$/ with ""
  var path = trim(p default "") replace /^\/+/ with ""
  ---
  if (isEmpty(path)) base0
  else base0 ++ "/" ++ path
}
fun stripSlash(s) = trim(s default "") replace /\/+$/ with ""
/** Many ingress routes only accept POST on the path with a trailing slash (…/broker/ vs …/broker → 404). */
fun ensureTrailingSlash(s) = do {
  var z = trim(s default "")
  ---
  if (isEmpty(z)) z
  else if (endsWith(z, "/")) z
  else z ++ "/"
}
var base = vars.normalizedBaseUrl default ""
var card = vars.agentCardValidated
var u = card.url default ""
var t = trim(u)
var proto = card.protocolVersion default ""
/** A2A v0.3 brokers speak JSON-RPC at card.url (root), not OpenAI /chat/completions */
var isA2aJsonRpc = startsWith(proto, "0.3")
---
if (isA2aJsonRpc)
  ensureTrailingSlash(t default base)
else if (!isEmpty(t) and (startsWith(t, "http://") or startsWith(t, "https://")))
  if (endsWith(t, "/"))
    stripSlash(t) ++ "/chat/completions"
  else
    t
else if (!isEmpty(t))
  joinBasePath(base, t)
else
  joinBasePath(base, "chat/completions")

%dw 2.0
output application/java
import trim from dw::core::Strings
var q = attributes.queryParams default {}
var u = q["url"] default q["URL"]
fun scalar(v) = v match {
  case is String -> trim(v)
  case is Array -> if (sizeOf(v) > 0) trim(v[0] as String) else ""
  else -> trim(v as String default "")
}
---
if (u == null) "" else scalar(u)

%dw 2.0
output application/java
import * from dw::core::Strings
var p = payload default {}
var raw =
  if (p is Object) (p.baseUrl default p["baseUrl"] default "")
  else ""
---
trim(raw as String default "")

%dw 2.0
output application/java
import * from dw::core::Strings
var p = payload default {}
var raw =
  if (p is Object) (p.alias default p["alias"] default "")
  else ""
---
trim(raw as String default "")

ee:message.ee:set-payload:
%dw 2.0
output application/json
var id = vars.brokerIdToDelete
var list = payload as Array
var filtered = list filter ($.id != id)
---
if (sizeOf(filtered) == sizeOf(list))
  { deleted: false, error: "Broker not found" }
else
  { deleted: true, id: id, brokers: filtered }

